export function syntheticCreditState(){const state=syntheticLedgerState();let l=configureCard(state.entryLedger,{id:'second-card',accountId:'card-account',name:'Segundo cartão sintético',closingDay:25,dueDay:5,onClosingDay:'next',archived:false});l=registerPurchase(l,{id:'synthetic-contract',description:'Contrato sintético com centavos',cardId:'second-card',operationDate:'2026-11-13',confirmed:true,firstPeriod:'2026-11',quote:{mode:'total',valueCents:10000,count:3}});l=registerRecurrence(l,{id:'synthetic-rec',description:'Recorrência sintética mensal',operationType:'expense',accountId:'cash-a',frequency:'monthly',startsOn:'2026-10-31',amountCents:2000,initialStatus:'active',status:'active',occurrences:[],events:[]});l=generateOccurrences(l,'synthetic-rec','2026-10-01','2027-01-31');state.entryLedger=l;state.planning={version:1,goals:[{id:'synthetic-goal',name:'Meta preservada',category:'Casa',target:100000,monthly:10000,deadline:'',note:'',status:'active',months:{},movements:[{id:'synthetic-goal-initial',delta:10000,date:'2026-11-13',period:'2026-11',note:'Aporte sintético'}]}]};validate(state);return state}
